package com.logatron.investigation.application;
import com.logatron.common.error.ApiException;import com.logatron.investigation.domain.InvestigationModels.*;import com.logatron.investigation.web.InvestigationDtos.CreateInvestigationRequest;import org.springframework.stereotype.Component;import java.time.*;import java.util.Locale;import java.util.regex.*;
@Component public class ControlledInvestigationPlanner {
 private static final Pattern ORDER=Pattern.compile("(?i)\\border(?:\\s+token)?\\s*[#:=]?\\s*([A-Za-z0-9._-]+)"),AUCTION=Pattern.compile("(?i)\\bauction\\s*[#:=]?\\s*([A-Za-z0-9._-]+)"),TRACE=Pattern.compile("(?i)\\b([0-9a-f]{32})\\b"),REQUEST=Pattern.compile("(?i)\\brequest(?:\\s+id)?\\s*[#:=]?\\s*([A-Za-z0-9._-]+)");
 public InvestigationQuery plan(CreateInvestigationRequest r,Clock clock){if(r==null||r.projectId()==null)throw ApiException.invalid("An authorized project is required.");Instant to=r.to()==null?clock.instant():r.to(),from=r.from()==null?to.minus(Duration.ofMinutes(30)):r.from();IdentifierType type=r.identifierType();String value=r.identifierValue();if(type==null){String q=r.question()==null?"":r.question();Match match=match(q);type=match.type();value=match.value();}try{return new InvestigationQuery(r.projectId(),r.environmentId(),from,to,type==null?IdentifierType.SCOPE:type,value);}catch(IllegalArgumentException ex){throw ApiException.invalid(ex.getMessage());}}
 private Match match(String q){Matcher m=TRACE.matcher(q);if(m.find())return new Match(IdentifierType.TRACE_ID,m.group(1).toLowerCase(Locale.ROOT));m=ORDER.matcher(q);if(m.find())return new Match(IdentifierType.ORDER_TOKEN,m.group(1));m=AUCTION.matcher(q);if(m.find())return new Match(IdentifierType.AUCTION_ID,m.group(1));m=REQUEST.matcher(q);if(m.find())return new Match(IdentifierType.REQUEST_ID,m.group(1));return new Match(IdentifierType.SCOPE,null);}private record Match(IdentifierType type,String value){}
}

